const S={token:'',user:null,data:null,demo:false,page:'dashboard',group:'',item:'',record:'',editingId:'',assignmentId:'',year:String(new Date().getFullYear()),cycle:'Penilaian Kendiri',settingsTab:'users',dirty:false,pending:null,filters:{search:'',group:'',status:'',context:''},catalog:{search:'',group:'',aspect:''}};
