const item=id=>I.items.find(i=>i.id===id),group=id=>I.groups.find(g=>g.id===id),record=id=>S.data?.records.find(r=>r.id===id);
const records=()=>S.data.records.filter(r=>String(r.year)===S.year&&r.cycle===S.cycle);
const scoped=g=>S.user.role==='admin'||S.user.role==='penyelaras'&&S.user.scopes.includes(g);
const editable=r=>S.user.role==='admin'||(scoped(r.group)||r.ownerId===S.user.id||r.assignedTo===S.user.id)&&['Draf','Perlu Pembetulan'].includes(r.status);
const initials=n=>(n||'S').split(' ').slice(0,2).map(w=>w[0]).join('').toUpperCase();
const date=v=>v?new Date(v.length===10?v+'T00:00:00':v).toLocaleDateString('ms-MY',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}):'—';
const today=()=>{const p=new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Kuala_Lumpur'}).formatToParts(new Date());const v=t=>p.find(x=>x.type===t).value;return v('year')+'-'+v('month')+'-'+v('day');};
const num=n=>n===null||n===undefined?'—':Number(n).toLocaleString('ms-MY',{maximumFractionDigits:2});
const safeURL=v=>{try{const u=new URL(v,location.href);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}};
