function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',5000);}
function busy(on){busyCount=Math.max(0,busyCount+(on?1:-1));$('#busy').hidden=!busyCount;}
function remember(){if(S.demo)return;try{sessionStorage.setItem('skas-v2-session',JSON.stringify({token:S.token,user:S.user}));}catch{}}
function forget(){try{sessionStorage.removeItem('skas-v2-session');}catch{}}
async function api(action,payload={}){
 if(S.demo)return demoAPI(action,payload);
 if(!navigator.onLine)throw new Error('Tiada Internet. Sambung semula untuk membaca atau menyimpan rekod.');
 if(action!=='health'&&!apiReady){const h=await api('health');if(!h.ready)throw new Error('Jalankan setupSystem() versi 2 dahulu.');apiReady=true;}
 busy(true);const c=new AbortController(),timeout=setTimeout(()=>c.abort(),90000);
 try{const res=await fetch(C.apiUrl,{method:action==='health'?'GET':'POST',redirect:'follow',credentials:'omit',cache:'no-store',headers:action==='health'?{}:{'Content-Type':'text/plain;charset=utf-8'},body:action==='health'?undefined:JSON.stringify({action,token:S.token,requestId:clientId(),...payload}),signal:c.signal});let out;try{out=JSON.parse(await res.text());}catch{throw new Error('Respons bukan JSON. Pastikan tiga fail .gs dipasang dan Web App dideploy kepada versi baharu dengan akses Anyone.');}
 if(!res.ok||!out.ok){if(out.code==='UNAUTHORIZED'&&action!=='login'){S.token='';S.user=null;S.data=null;S.dirty=false;forget();loginView();}throw new Error(out.error||'Permintaan gagal.');}
 if(action==='health'){if(out.app!=='SKAS'||out.version!=='2.0.0'||out.sourceHash!==I.source.sha256)throw new Error('Endpoint belum menggunakan instrumen v2 yang sama. Pasang Code.gs, Instrumen.gs dan Scoring.gs, kemudian Deploy New version.');return out;}return out.data;
 }catch(err){if(err.name==='AbortError')throw new Error('Masa menunggu tamat. Muat semula untuk menyemak hasil sebelum cuba menyimpan lagi.');if(err instanceof TypeError)throw new Error('Tidak dapat menghubungi Apps Script. Semak URL /exec, Internet dan akses deployment Anyone.');throw err;}finally{clearTimeout(timeout);busy(false);}
}
async function load(){S.data=await api('bootstrap');S.user=S.data.user;remember();render();}
