function render(){
 if(!S.data)return loginView();const u=S.user,years=[...new Set([S.year,String(new Date().getFullYear()),...S.data.records.map(r=>String(r.year)),...S.data.assignments.map(t=>String(t.year))])].sort().reverse(),cycles=[...new Set([S.cycle,S.data.settings.cycle||'Penilaian Kendiri',...S.data.records.map(r=>r.cycle),...S.data.assignments.map(t=>t.cycle)])];
 $('#app').innerHTML=`<div class="shell"><div class="mobile-shade" data-action="menu"></div><aside class="sidebar"><div class="brand system-sidebar-brand"><img class="sidebar-system-logo" src="${esc(C.systemLogo||'./assets/logo-sistem.png')}" alt="Logo SKPM Kualiti@Sekolah"><small>PENGURUSAN KUALITI SEKOLAH</small></div><div class="school-pill"><b>${esc(school())}</b><small>Pengurusan berasaskan evidens</small></div><div class="nav-group"><p class="nav-label">RUANG KERJA</p>${nav('dashboard','Dashboard','grid')}${nav('catalog','Instrumen & Rubrik','book')}${nav('records','Penilaian & Evidens','file',`<span class="count">${records().length}</span>`)}${nav('tasks','Tugasan PPS','users')}${nav('reports','Laporan & Analisis','chart')}</div><div class="nav-group"><p class="nav-label">BIDANG PENGURUSAN</p>${I.groups.map(g=>`<button type="button" class="nav-btn group-nav ${S.page==='catalog'&&S.catalog.group===g.id?'selected':''}" data-action="group" data-id="${g.id}"><span class="nav-dot" style="--group:${g.color}"></span><span>${g.id==='A'?'A · ':g.id==='5'?'5 · ':'S'+g.id+' · '}${esc(g.title.replace('Pengurusan ',''))}</span></button>`).join('')}</div><div class="nav-bottom">${u.role==='admin'?nav('settings','Tetapan Sistem','settings'):''}<button class="nav-btn" data-action="password">${icon('shield')}<span>Tukar Kata Laluan</span></button><button class="nav-btn" data-action="logout">${icon('logout')}<span>${S.demo?'Keluar Demo':'Log Keluar'}</span></button></div></aside><div class="workspace">${systemHeader()}<div class="topbar"><div class="row"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Buka menu">${icon('menu')}</button><div class="topbar-heading">${icon('shield')}<span>Ruang Kerja Kualiti Sekolah</span></div></div><div class="top-actions"><label class="sr-only" for="school-year">Tahun</label><select id="school-year">${years.map(y=>option(y,y,S.year)).join('')}</select><label class="sr-only" for="cycle">Fasa penilaian</label><select id="cycle">${cycles.map(c=>option(c,c,S.cycle)).join('')}</select><button class="icon-btn" data-action="refresh" aria-label="Muat semula">${icon('refresh')}</button><div class="row"><span class="avatar">${esc(initials(u.name))}</span><div class="profile-label"><div class="profile-name">${esc(u.name)}</div><div class="profile-role">${roles[u.role]}</div></div></div></div></div>${S.demo?'<div class="demo-banner">MOD DEMONSTRASI · Data contoh. Tiada perubahan dihantar ke Google Sheets.</div>':''}${!navigator.onLine?'<div class="offline-banner">Luar talian · Simpanan dan akses semula data memerlukan Internet.</div>':''}<main class="main" id="main"></main></div></div>`;renderPage();
}
function renderPage(){
 const el=$('#main');el.className='main fade';document.body.classList.remove('menu-open');
 const names={dashboard:'Dashboard',catalog:'Instrumen & Rubrik',item:'Butiran Instrumen',records:'Penilaian & Evidens',detail:'Butiran Penilaian',edit:'Borang Penilaian',tasks:'Tugasan PPS',reports:'Laporan & Analisis',settings:'Tetapan Sistem'};
 el.innerHTML=`<div class="breadcrumb"><button data-action="nav" data-page="dashboard">Utama</button>${S.page==='dashboard'?'':icon('chevron')+`<span>${names[S.page]||''}</span>`}<span class="spacer"></span><span class="source-chip">${icon('book')}Instrumen 75 halaman</span></div>`+({dashboard:dashboard,catalog:catalogPage,item:itemPage,records:recordsPage,detail:detailPage,edit:editPage,tasks:tasksPage,reports:reportsPage,settings:settingsPage}[S.page]||dashboard)()+`<footer class="footer"><span>SK@S 2.0 · ${esc(school())}</span><span>Berpandukan instrumen. Diperkukuh evidens.</span></footer>`;
}
function filtered(){const f=S.filters;return records().filter(r=>(!f.group||r.group===f.group)&&(!f.status||r.status===f.status)&&(!f.context||r.context.toLowerCase().includes(f.context.toLowerCase()))&&(!f.search||(r.itemId+' '+r.title+' '+r.context+' '+r.officer).toLowerCase().includes(f.search.toLowerCase()))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));}
function coverage(gid,rs=records()){const its=I.items.filter(i=>!gid||i.group===gid),seen=new Set(rs.map(r=>r.itemId)),done=its.filter(i=>seen.has(i.id)).length;return {done,total:its.length,percent:its.length?Math.round(done/its.length*100):0};}
function dashboard(){
 const rs=records(),c=coverage(),pending=rs.filter(r=>r.status==='Dihantar').length,verified=rs.filter(r=>r.status==='Disahkan').length,ev=rs.reduce((n,r)=>n+r.evidence.length,0),mean=E.summarize(rs.filter(r=>r.status==='Disahkan'));
 return title('Dashboard Sekolah','Selamat datang, '+S.user.name+'. Mari teruskan usaha meningkatkan kualiti sekolah.',btn('Penilaian Baharu','new','plus','primary'))+`<section class="hero v2-hero"><div class="hero-copy"><div class="eyebrow"><span class="hero-dot"></span> INSTRUMEN SKPM KUALITI@SEKOLAH</div><h2>Kekuatan dikenal pasti.<br>Kualiti dipertingkat bersama.</h2><p>Satu ruang untuk profil sekolah, penilaian pengurusan,<br>pencerapan PdPc dan pencapaian warga sekolah.</p><div class="row wrap">${btn('Terokai Instrumen','nav-catalog','arrow')}${btn('Pasang Aplikasi','install','download','hero-secondary')}</div></div><div class="v2-art" aria-hidden="true"><div class="art-orbit"></div><div class="school-art"><div class="school-roof"></div><div class="school-body"><span>SK@S</span><i></i><i></i><i></i><i></i><b></b></div></div><div class="art-float one">${icon('shield')}<span>Evidens tersusun</span></div><div class="art-float two">${icon('check')}<span>Penilaian lebih jelas</span></div><div class="art-star">✦</div></div></section><div class="metrics">${[['Item Direkod',c.done+'/'+c.total,'book','Liputan '+c.percent+'% · bukan skor kualiti',''],['Menunggu Semakan',pending,'clock','Rekod menunggu tindakan penyelaras','Dihantar'],['Penilaian Disahkan',verified,'check','Rekod telah melalui semakan','Disahkan'],['Jumlah Evidens',ev,'link','Fail dan pautan rujukan penilaian','']].map(x=>`<button class="metric" data-action="metric" data-status="${x[4]}"><div class="metric-top">${x[0]}<span class="metric-icon">${icon(x[2])}</span></div><strong>${x[1]}</strong><small>${x[3]}</small></button>`).join('')}</div><div class="section-title"><h3>Tiga bahagian. Satu gambaran menyeluruh.</h3><span class="subtle-pill">${esc(S.year)} · ${esc(S.cycle)}</span></div><div class="pillar-grid">${[['A','Kekuatan Kami','Kenali sumber dan potensi sekolah.','9 aspek · 22 medan','sprout'],['B','Pengurusan Kami','Nilai amalan berpandukan rubrik.','50 item · 216 tindakan','building'],['5','Pencapaian Kami','Rekod hasil yang dicapai bersama.','11 item · 36 medan','chart']].map(([id,h,p,n,ico])=>`<button class="pillar pillar-${id}" data-action="pillar" data-id="${id}"><span class="pillar-icon">${icon(ico)}</span><div><h3>${h}</h3><p>${p}</p><small>${n}</small></div>${icon('arrow')}</button>`).join('')}</div><div class="dashboard-bottom"><section class="panel"><div class="section-title"><h3>Penilaian terkini</h3>${btn('Lihat semua','nav-records','arrow','ghost small')}</div>${rs.length?[...rs].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,4).map(r=>`<div class="activity-row"><span class="activity-symbol" style="color:${group(r.group).color}">${icon(group(r.group).icon)}</span><div class="spacer"><button class="text-link" data-action="record" data-id="${r.id}">${esc(r.title)}</button><div class="activity-meta">${esc(r.itemId)} · ${esc(r.context)} · ${date(r.date)}</div></div>${badge(r.status)}</div>`).join(''):empty('Penilaian pertama bermula di sini','Pilih item instrumen dan rekod amalan sekolah anda.')}</section><section class="panel score-panel"><div class="section-title"><h3>Pandangan ringkas</h3><span class="tag">DALAMAN</span></div><div class="big-score">${num(mean.mean)}<small>/ 4</small></div><p class="muted" style="font-size:11px">Purata tindakan dalam rekod rubrik yang lengkap dan disahkan.</p><div class="mini-stat-grid"><div><b>${mean.actions}</b><small>tindakan dinilai</small></div><div><b>${rs.filter(r=>r.notApplicable).length}</b><small>rekod Tidak Berkaitan</small></div></div><div class="chart-note">Jumlah skor ÷ bilangan tindakan dinilai. Tiada wajaran rasmi keseluruhan dinyatakan dalam PDF. Metrik A dan Standard 5 tidak digabungkan dalam purata ini.</div></section></div><div class="section-title" style="margin-top:25px"><h3>Bidang pengurusan</h3><small>Klik bidang untuk membuka instrumen.</small></div><div class="group-grid">${I.groups.map(g=>{const x=coverage(g.id);return `<button class="group-card" data-action="group" data-id="${g.id}" style="--group:${g.color}"><div class="row between"><span class="group-symbol">${icon(g.icon)}</span><span class="group-code">${g.id==='A'?'BAHAGIAN A':'STANDARD '+g.id}</span></div><h3>${esc(g.title)}</h3><p>${esc(g.description)}</p><div class="row between"><small>${x.done}/${x.total} item direkod</small>${icon('arrow')}</div><div class="group-progress"><i style="width:${x.percent}%"></i></div></button>`;}).join('')}</div>`;
}
function catalogAspects(){const f=S.catalog;return I.aspects.filter(a=>(!f.group||a.group===f.group)&&(f.section!=='B'||!['A','5'].includes(a.group)));}
function catalogItems(){const f=S.catalog;return I.items.filter(i=>(f.section!=='B'||i.kind==='rubric')&&(!f.group||i.group===f.group)&&(!f.aspect||i.aspectId===f.aspect)&&(!f.search||(i.id+' '+i.label+' '+i.quality+' '+i.actions.map(a=>a.label).join(' ')).toLowerCase().includes(f.search.toLowerCase())));}
function catalogCards(){const list=catalogItems();return list.length?`<div class="record-count">${list.length} item instrumen</div><div class="catalog-grid">${list.map(i=>{const rs=records().filter(r=>r.itemId===i.id),g=group(i.group);return `<button class="catalog-card" data-action="item" data-id="${i.id}" style="--group:${g.color}"><div class="row between"><span class="code-badge">${esc(i.code)}</span><span class="tag">${i.kind==='rubric'?'Rubrik 0–4':'Metrik'}</span></div><h3>${esc(i.label)}</h3><p>${esc(i.quality)}</p><div class="catalog-foot"><span>${i.kind==='rubric'?i.actions.length+' tindakan':i.fields.length+' medan'} · hlm. ${i.pages.join(', ')}</span><span>${rs.length?rs.length+' rekod':'Belum direkod'} ${icon('arrow')}</span></div></button>`;}).join('')}</div>`:empty('Item tidak ditemui','Ubah carian atau pilih bidang yang lain.');}
function catalogPage(){const f=S.catalog,g=group(f.group);return title(g?g.title:f.section==='B'?'Pengurusan Kami':'Instrumen & Rubrik',g?g.description:f.section==='B'?'Standard 1–4 · 50 item pengurusan dan 216 tindakan penskoran.':'Terokai 70 item dengan pernyataan, tindakan dan panduan penskoran daripada PDF.',`<a href="${I.source.pdf}" target="_blank" rel="noopener" class="btn">${icon('book')}Buka PDF Sumber</a>`)+`<div class="catalog-filters"><div class="search-input">${icon('search')}<input id="catalog-search" value="${esc(f.search)}" placeholder="Cari kod, tajuk atau tindakan…" aria-label="Cari instrumen"></div><select id="catalog-group" aria-label="Bidang">${option('','Semua Bidang',f.section==='B'?'B':f.group)}${option('B','Pengurusan Kami (Standard 1–4)',f.section==='B'?'B':f.group)}${I.groups.map(g=>option(g.id,(g.id==='A'?'A':'S'+g.id)+' · '+g.title,f.section==='B'?'B':f.group)).join('')}</select><select id="catalog-aspect" aria-label="Aspek">${option('','Semua Aspek',f.aspect)}${catalogAspects().map(a=>option(a.id,a.id+' · '+a.title,f.aspect)).join('')}</select></div><div id="catalog-results">${catalogCards()}</div>`;}
function rubricTable(a){return `<div class="rubric-table"><table><thead><tr>${[4,3,2,1,0].map(n=>`<th>Skor ${n}</th>`).join('')}</tr></thead><tbody><tr>${[4,3,2,1,0].map(n=>`<td>${esc(a.rubric[n])}</td>`).join('')}</tr></tbody></table></div>`;}
function itemPage(){const i=item(S.item);if(!i)return empty('Item tidak ditemui');const rs=records().filter(r=>r.itemId===i.id),aspect=I.aspects.find(a=>a.id===i.aspectId);return title(i.code+' · '+i.label,group(i.group).title,pdfButton(i.page)+btn('Mulakan Penilaian','start','plus','primary',i.id))+`<div class="item-overview panel"><span class="eyebrow">${esc(aspect?.id||'')} · ${esc(aspect?.title||'')}</span><h3>${esc(i.quality)}</h3>${i.criterion?`<p><b>Kriteria kritikal:</b> ${esc(i.criterion)}</p>`:''}<p>${esc(i.procedure)}</p></div><div class="section-title"><h3>${i.kind==='rubric'?'Tindakan & Panduan Penskoran':'Medan Data Instrumen'}</h3><small>Rujuk halaman ${i.pages.join(', ')}</small></div>${i.kind==='rubric'?i.actions.map((a,n)=>`<details class="action-card" ${n===0?'open':''}><summary><span class="action-letter">${a.id.toUpperCase()}</span><b>${esc(a.label)}</b><span class="spacer"></span><span class="tag">0–4</span>${icon('chevron')}</summary><div class="action-body">${rubricTable(a)}<div class="row" style="margin-top:12px">${pdfButton(a.page)}</div></div></details>`).join(''):`<div class="panel metric-definition">${i.fields.map(f=>`<div class="definition-row"><div><b>${esc(f.title)}</b><p>${f.type==='ratio'?esc(f.numerator)+' ÷ '+esc(f.denominator)+' × 100':esc(f.note||'Nilai mengikut unit instrumen.')}${f.referenceYearOffset?' · Gunakan rumusan tahun '+(Number(S.year)-1):''}</p></div><span class="tag">${esc(f.unit)}</span></div>`).join('')}</div>`}<div class="section-title" style="margin-top:27px"><h3>Penilaian & Evidens Berkaitan</h3><small>${rs.length} rekod · ${esc(S.cycle)}</small></div>${recordTable(rs)}`;}
function filtersHTML(){const f=S.filters;return `<div class="filters"><div><label class="filter-label" for="filter-search">Carian rekod</label><input id="filter-search" data-filter="search" value="${esc(f.search)}" placeholder="Kod, tajuk atau pegawai…"></div><div><label class="filter-label" for="filter-group">Bidang</label><select id="filter-group" data-filter="group">${option('','Semua Bidang',f.group)}${I.groups.map(g=>option(g.id,g.id+' · '+g.title,f.group)).join('')}</select></div><div><label class="filter-label" for="filter-status">Status</label><select id="filter-status" data-filter="status">${option('','Semua Status',f.status)}${statuses.map(s=>option(s,s,f.status)).join('')}</select></div><div><label class="filter-label" for="filter-context">Konteks / Unit</label><input id="filter-context" data-filter="context" value="${esc(f.context)}" placeholder="Sekolah, panitia, guru…"></div></div>`;}
function recordScore(r){if(r.notApplicable)return '<span class="tag">Tidak Berkaitan</span>';if(r.kind==='metric')return `<b>${r.computed.scored}/${r.computed.total}</b><small> medan berisi</small>`;return `<b>${num(r.computed.mean)}</b><small> / 4${!r.computed.complete?' · separa':''}</small>`;}
function recordTable(rs){return rs.length?`<div class="record-count">${rs.length} rekod · Tahun ${esc(S.year)} · ${esc(S.cycle)}</div><div class="table-wrap"><table><thead><tr><th>Item / Penilaian</th><th>Konteks / Pegawai</th><th>Nilai</th><th>Evidens</th><th>Status</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td style="min-width:210px"><span class="table-code">${esc(r.itemId)}</span><button class="text-link" data-action="record" data-id="${r.id}">${esc(r.title)}</button><small>${date(r.date)}</small></td><td style="min-width:150px"><b style="font-size:11px">${esc(r.context)}</b><small style="display:block">${esc(r.officer)}</small></td><td style="white-space:nowrap">${recordScore(r)}</td><td>${r.evidence.length}</td><td>${badge(r.status)}</td><td><button class="icon-btn" data-action="record" data-id="${r.id}" aria-label="Buka ${esc(r.title)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty();}
function recordsPage(){return title('Penilaian & Evidens','Jejaki penilaian, semakan dan dokumen sokongan mengikut instrumen.',btn('Eksport CSV','csv','download')+btn('Penilaian Baharu','new','plus','primary'))+filtersHTML()+`<div id="record-results">${recordTable(filtered())}</div>`;}
function field(label,name,value='',type='text',required=false,cls=''){return `<div class="form-field ${cls}"><label for="f-${esc(name)}">${esc(label)}${required?' *':''}</label>${type==='textarea'?`<textarea id="f-${esc(name)}" name="${esc(name)}" maxlength="4000" ${required?'required':''}>${esc(value)}</textarea>`:`<input id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="12" autocomplete="new-password"':''} ${type==='number'?'min="0" step="any"':''}>`}</div>`;}
function selectField(label,name,html){return `<div class="form-field"><label for="f-${esc(name)}">${esc(label)}</label><select id="f-${esc(name)}" name="${esc(name)}">${html}</select></div>`;}
function editPage(){
 const old=S.editingId?record(S.editingId):null,i=item(old?.itemId||S.item);if(!i)return empty('Pilih item instrumen dahulu');const t=S.assignmentId?S.data.assignments.find(x=>x.id===S.assignmentId):null;
 const r=old||{year:t?.year||S.year,cycle:t?.cycle||S.cycle,context:t?.context||'',date:today(),assignedTo:t?.assignedTo||S.user.id,officer:S.data.users.find(u=>u.id===(t?.assignedTo||S.user.id))?.name||S.user.name,ratings:{},metrics:{},notApplicable:false,naReason:'',summary:'',improvement:''};
 return title((old?'Sunting':'Penilaian Baharu')+' · '+i.code,i.label,pdfButton(i.page))+`<form id="assessment-form" data-item="${i.id}" data-id="${old?.id||''}" data-revision="${old?.revision||0}" data-assignment="${old?.assignmentId||t?.id||''}"><div class="assessment-layout"><div><section class="panel" style="margin-bottom:20px"><div class="section-title"><h3>Maklumat penilaian</h3><span class="tag">${i.kind==='rubric'?'Rubrik 0–4':'Data Metrik'}</span></div><div class="form-grid">${field('Tahun','year',r.year,'number',true)}${field('Fasa penilaian','cycle',r.cycle,'text',true)}${field(i.group==='4'?'Konteks: guru / kelas / subjek / sesi':'Konteks: sekolah / panitia / unit','context',r.context,'text',true,'span2')}${field('Tarikh penilaian / pencerapan','date',r.date,'date',true)}${field('Nama pegawai / guru','officer',r.officer,'text',true)}<div class="span2">${selectField('Akaun pegawai ditugaskan','assignedTo',S.data.users.filter(u=>u.active&&(S.user.role!=='guru'||u.id===S.user.id)).map(u=>option(u.id,u.name,r.assignedTo)).join(''))}</div></div>${t||old?.assignmentId?'<div class="notice">Rekod ini dipautkan kepada tugasan PPS. Tahun, fasa, konteks dan pegawai mesti sepadan dengan tugasan.</div>':''}<label class="na-toggle"><input type="checkbox" name="notApplicable" ${r.notApplicable?'checked':''}><span><b>Item ini Tidak Berkaitan</b><small>Gunakan sebab yang jelas. Ia tidak ditukar menjadi skor sifar.</small></span></label><div id="whole-na-reason" ${r.notApplicable?'':'hidden'}>${field('Sebab Tidak Berkaitan','naReason',r.naReason,'textarea')}</div></section><fieldset id="assessment-fields" ${r.notApplicable?'disabled':''}><div class="section-title"><h3>${i.kind==='rubric'?'Nilai Setiap Tindakan':'Data & Pencapaian'}</h3><small>${i.kind==='rubric'?'Pilih skor berpandukan rubrik':'Nilai mengikut unit asal'}</small></div>${i.kind==='rubric'?i.actions.map(a=>scoreCard(a,r.ratings[a.id])).join(''):metricCards(i,r.metrics,r.year)}</fieldset><section class="panel" style="margin-top:20px"><h3 style="margin-bottom:18px">Ulasan & Penambahbaikan</h3>${field('Ulasan pelaksanaan / dapatan','summary',r.summary,'textarea')}${field('Tindakan penambahbaikan / susulan','improvement',r.improvement,'textarea')}<div class="notice">Simpan draf dahulu untuk menambah fail atau pautan evidens. Draf boleh mempunyai skor atau data yang belum lengkap.</div><div class="form-error" role="alert"></div><div class="modal-actions">${btn('Batal','cancel-edit')}<button class="btn" type="submit" name="intent" value="draft">Simpan Draf</button><button class="btn primary" type="submit" name="intent" value="submit">Hantar untuk Semakan ${icon('arrow')}</button></div></section></div><aside class="assessment-side"><div class="panel sticky"><span class="eyebrow">RINGKASAN PENILAIAN</span><h3 style="margin:12px 0">${esc(i.label)}</h3><p class="muted" style="font-size:11px">${esc(i.quality)}</p><div id="score-preview">${scorePreview(i,r)}</div><div class="chart-note">${i.kind==='rubric'?'Skor ditentukan berdasarkan rubrik PDF. Ringkasan purata ialah kiraan dalaman, bukan skor keseluruhan rasmi.':'Peratus, GPS, PNGK dan bilangan dikekalkan mengikut unit. Tiada skor gabungan dihasilkan.'}</div><div style="margin-top:17px">${pdfButton(i.page)}</div></div></aside></div></form>`;
}
function scoreCard(a,v={}){return `<section class="score-card"><div class="score-card-head"><span class="action-letter">${a.id.toUpperCase()}</span><h3>${esc(a.label)}</h3></div><div class="score-options" role="radiogroup" aria-label="Skor tindakan ${a.id}">${[0,1,2,3,4].map(n=>`<label class="score-choice"><input type="radio" name="score:${a.id}" value="${n}" ${v.score!==null&&v.score!==undefined&&Number(v.score)===n?'checked':''}><span>${n}</span></label>`).join('')}<button type="button" class="clear-score" data-action="clear-score" data-id="${a.id}">Kosongkan</button></div><details class="rubric-disclosure"><summary>${icon('book')}Lihat panduan skor 0–4 ${icon('chevron')}</summary>${rubricTable(a)}</details><div class="form-field compact"><label for="note-${a.id}">Ulasan tindakan / rujukan evidens</label><textarea id="note-${a.id}" name="note:${a.id}" rows="2" maxlength="4000" placeholder="Catatan dapatan atau rujukan dokumen…">${esc(v.note||'')}</textarea></div></section>`;}
function metricCards(i,values,year){let last='';return i.fields.map(f=>{const v=values[f.id]||{},h=f.assessment&&f.assessment!==last?`<div class="assessment-divider"><b>${esc(f.assessment)}</b><small>TP1–TP6 bagi konteks mata pelajaran yang sama; jumlah 100%.</small></div>`:'';last=f.assessment||last;return h+`<section class="metric-card" data-field="${f.id}"><div class="row between"><h3>${esc(f.title)}</h3><span class="tag">${esc(f.unit)}</span></div>${f.referenceYearOffset?`<div class="notice">Gunakan Skor Rumusan Standard 4 tahun <b>${Number(year)-1}</b>.</div>`:''}<fieldset class="metric-inputs" ${v.na?'disabled':''}>${f.type==='ratio'?`<div class="form-grid">${numberField(f.numerator,'metric:'+f.id+':numerator',v.numerator,true)}${numberField(f.denominator,'metric:'+f.id+':denominator',v.denominator,true)}</div><div class="ratio-result" data-ratio="${f.id}">Peratus: <b>${v.value!==null&&v.value!==undefined?num(v.value)+'%':'Tidak dapat dikira / belum lengkap'}</b></div>`:numberField('Nilai ('+f.unit+')','metric:'+f.id+':value',v.value,f.unit==='bilangan',f.unit==='%')}${f.note?`<small>${esc(f.note)}</small>`:''}</fieldset><label class="check-row"><input type="checkbox" name="metric:${f.id}:na" ${v.na?'checked':''}><span>Medan ini Tidak Berkaitan</span></label><div class="metric-na-reason" ${v.na?'':'hidden'}>${field('Sebab Tidak Berkaitan','metric:'+f.id+':reason',v.reason||'')}</div></section>`;}).join('');}
function numberField(label,name,v,integer=false,percent=false){return `<div class="form-field"><label for="${esc(name)}">${esc(label)}</label><input id="${esc(name)}" name="${esc(name)}" type="number" step="${integer?'1':'any'}" min="0" ${percent?'max="100"':''} value="${esc(v??'')}" placeholder="Belum diisi"></div>`;}
function formRecord(form){const i=item(form.dataset.item),get=n=>form.elements.namedItem(n)?.value??'',ratings={},metrics={};if(i.kind==='rubric')i.actions.forEach(a=>{const choice=[...form.querySelectorAll('input[type="radio"]')].find(x=>x.name==='score:'+a.id&&x.checked);ratings[a.id]={score:choice?Number(choice.value):null,note:get('note:'+a.id)};});else i.fields.forEach(f=>metrics[f.id]={value:get('metric:'+f.id+':value'),numerator:get('metric:'+f.id+':numerator'),denominator:get('metric:'+f.id+':denominator'),na:!!form.elements.namedItem('metric:'+f.id+':na')?.checked,reason:get('metric:'+f.id+':reason')});return {id:form.dataset.id,revision:form.dataset.revision,itemId:i.id,year:get('year'),cycle:get('cycle'),context:get('context'),date:get('date'),officer:get('officer'),assignedTo:get('assignedTo'),assignmentId:form.dataset.assignment,ratings,metrics,notApplicable:form.elements.notApplicable.checked,naReason:get('naReason'),summary:get('summary'),improvement:get('improvement')};}
function scorePreview(i,r){try{const result=E.evaluate(i,r,false,r.year||S.year),c=result.computed;if(c.notApplicable)return '<div class="preview-na">Tidak Berkaitan</div><p class="muted" style="font-size:11px">Tidak dimasukkan dalam purata rubrik.</p>';return `<div class="preview-number">${i.kind==='rubric'?num(c.mean):c.scored}<small>${i.kind==='rubric'?'/ 4':'/ '+c.total+' medan'}</small></div><div class="score-completion"><span>${c.scored} ${i.kind==='rubric'?'daripada '+c.total+' tindakan':'medan berisi'}${c.excluded?' · '+c.excluded+' TB':''}</span><b>${c.complete?'Lengkap':'Draf / Separa'}</b></div>${i.kind==='rubric'?`<div class="group-progress"><i style="width:${c.total?c.scored/c.total*100:0}%"></i></div><p class="score-formula">Jumlah ${num(c.sum)} ÷ ${c.scored||'—'} tindakan dinilai</p>`:''}`;}catch(e){return `<div class="inline-error">${esc(e.message)}</div>`;}}
function updatePreview(){const form=$('#assessment-form');if(!form)return;const r=formRecord(form),i=item(r.itemId);$('#score-preview').innerHTML=scorePreview(i,r);if(i.kind==='metric'){for(const f of i.fields.filter(f=>f.type==='ratio')){const v=r.metrics[f.id],n=v.numerator===''?null:Number(v.numerator),d=v.denominator===''?null:Number(v.denominator),node=[...document.querySelectorAll('[data-ratio]')].find(x=>x.dataset.ratio===f.id);if(node)node.innerHTML='Peratus: <b>'+(v.na?'Tidak Berkaitan':n!==null&&d>0?num(E.round(n/d*100))+'%':'Tidak dapat dikira / belum lengkap')+'</b>';}}}
function evidenceList(r){return r.evidence.length?r.evidence.map(e=>`<div class="evidence">${icon(e.mimeType==='link'?'link':'file')}<a href="${safeURL(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.name)}<small style="display:block">${e.actionId?'Tindakan/medan '+esc(e.actionId)+' · ':''}${e.mimeType==='link'?'Pautan':num(e.size/1024)+' KB'}</small></a>${editable(r)?`<button type="button" class="icon-btn" data-action="remove-evidence" data-id="${e.id}" data-record="${r.id}" aria-label="Buang rujukan evidens">${icon('close')}</button>`:''}</div>`).join(''):'<p class="muted" style="font-size:11px">Belum ada fail atau pautan evidens.</p>';}
function detailPage(){const r=record(S.record);if(!r)return empty('Rekod tidak ditemui');const i=item(r.itemId),reviews=S.data.reviews.filter(x=>x.recordId===r.id);return title(r.itemId+' · '+r.title,r.context+' · '+r.year+' · '+r.cycle,btn('Cetak / PDF','print-record','print','',r.id)+(editable(r)?btn('Sunting','edit','edit','primary',r.id):''))+`<div class="detail-grid"><div><section class="panel" style="margin-bottom:20px"><div class="row between"><h3>Ringkasan Penilaian</h3>${badge(r.status)}</div><div class="detail-score">${recordScore(r)}</div><dl class="detail-meta">${[['Pegawai',r.officer],['Tarikh',date(r.date)],['Bidang',group(r.group).title],['Konteks',r.context]].map(([k,v])=>`<div class="detail-item"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${r.notApplicable?`<div class="notice">Tidak Berkaitan: ${esc(r.naReason)}</div>`:r.kind==='rubric'?`<div class="chart-note">Purata dalaman: jumlah skor ${num(r.computed.sum)} ÷ ${r.computed.scored} tindakan dinilai. ${r.computed.complete?'Semua tindakan lengkap.':'Penilaian separa.'}</div>`:''}</section>${r.notApplicable?'':r.kind==='rubric'?i.actions.map(a=>{const v=r.ratings[a.id];return `<section class="score-card readonly"><div class="score-card-head"><span class="action-letter">${a.id.toUpperCase()}</span><h3>${esc(a.label)}</h3><span class="result-score">${num(v?.score)}<small>/4</small></span></div>${v?.score!==null&&v?.score!==undefined?`<p class="selected-rubric">${esc(a.rubric[v.score])}</p>`:'<p class="muted">Belum dinilai.</p>'}${v?.note?`<p class="score-note">${esc(v.note)}</p>`:''}<details class="rubric-disclosure"><summary>${icon('book')}Lihat semua rubrik</summary>${rubricTable(a)}</details></section>`;}).join(''):`<section class="panel">${i.fields.map(f=>{const v=r.metrics[f.id]||{};return `<div class="definition-row"><div><b>${esc(f.title)}</b><p>${v.na?'Tidak Berkaitan: '+esc(v.reason):f.type==='ratio'?num(v.numerator)+' ÷ '+num(v.denominator)+' × 100':esc(f.referenceYearOffset?'Rumusan tahun '+(Number(r.year)-1):f.note||'')}</p></div><div class="metric-value">${v.na?'TB':num(v.value)}<small>${v.na?'':esc(f.unit)}</small></div></div>`;}).join('')}</section>`}<section class="panel" style="margin-top:20px"><h3>Ulasan Pelaksanaan</h3><p class="paragraph">${esc(r.summary||'Belum diisi.')}</p><h3>Tindakan Penambahbaikan</h3><p class="paragraph">${esc(r.improvement||'Belum diisi.')}</p><div class="row wrap" style="margin-top:18px">${editable(r)&&['Draf','Perlu Pembetulan'].includes(r.status)?btn('Hantar untuk Semakan','submit-record','check','teal',r.id):''}${scoped(r.group)&&r.status!=='Draf'?btn('Buka Semula','reopen','refresh','',r.id):''}${S.user.role==='admin'?btn('Padam','delete-record','trash','danger',r.id):''}</div><small style="display:block;margin-top:15px">Dikemas kini ${date(r.updatedAt)} · Revision ${r.revision}</small></section></div><aside><section class="panel" style="margin-bottom:20px"><div class="section-title"><h3>Evidens</h3>${editable(r)?btn('Tambah','evidence','plus','small',r.id):''}</div>${evidenceList(r)}<small style="display:block;margin-top:14px">Perkongsian fail mengikut kebenaran Google Drive.</small></section><section class="panel" style="margin-bottom:20px"><h3 style="margin-bottom:13px">Semakan & Pengesahan</h3>${reviews.length?reviews.map(v=>`<div class="review-item">${badge(v.status)}<p>${esc(v.feedback||'Penilaian disahkan.')}</p><small>${esc(v.reviewerName)} · ${date(v.createdAt)}</small></div>`).join(''):'<p class="muted" style="font-size:11px">Belum disemak.</p>'}${scoped(r.group)&&r.status==='Dihantar'?`<div style="margin-top:17px">${btn('Semak Penilaian','review','check','teal full',r.id)}</div>`:''}</section><section class="panel"><h3 style="margin-bottom:13px">Rujukan Instrumen</h3><p class="muted" style="font-size:11px;margin-bottom:15px">${esc(i.quality)}</p>${pdfButton(i.page)}<div style="margin-top:12px">${btn('Buka Item','item','book','ghost small',i.id)}</div></section></aside></div>`;}
function tasksPage(){const tasks=S.data.assignments.filter(t=>String(t.year)===S.year&&t.cycle===S.cycle);return title('Tugasan PPS','Selaraskan item, pegawai bertanggungjawab dan tarikh penghantaran.',S.user.role!=='guru'?btn('Tetapkan Tugasan','new-task','plus','primary'):'')+(tasks.length?`<div class="task-grid">${tasks.map(t=>{const r=S.data.records.find(x=>x.assignmentId===t.id),owner=S.data.users.find(u=>u.id===t.assignedTo),late=t.dueDate<today()&&!r;return `<section class="task-card"><div class="row between"><span class="code-badge">${esc(t.itemId)}</span>${r?badge(r.status):`<span class="tag ${late?'red':'orange'}">${late?'Lewat':'Belum Dimulakan'}</span>`}</div><h3>${esc(item(t.itemId)?.label||t.itemId)}</h3><p>${esc(t.context)}</p><div class="task-meta">${icon('users')}${esc(owner?.name||t.assignedTo)}</div><div class="task-meta">${icon('clock')}Tarikh akhir ${date(t.dueDate)}</div>${t.note?`<p class="task-note">${esc(t.note)}</p>`:''}<div class="row wrap" style="margin-top:18px">${r?btn('Buka Penilaian','record','arrow','primary small',r.id):btn('Mulakan','start-task','plus','primary small',t.id)}${scoped(t.group)&&!r?btn('Padam','delete-task','trash','ghost small',t.id):''}</div></section>`;}).join('')}</div>`:empty('Belum ada tugasan','Pentadbir atau penyelaras boleh menetapkan item kepada PPS.'));}
function reportsPage(){const rs=filtered(),m=E.summarize(rs.filter(r=>r.status==='Disahkan'));return title('Laporan & Analisis','Ringkasan mengikut tahun, fasa dan rekod yang boleh diakses.',btn('Eksport CSV','csv','download'))+filtersHTML()+`<div class="report-summary"><div><strong>${rs.length}</strong><span>rekod ditapis</span></div><div><strong>${rs.filter(r=>r.status==='Disahkan').length}</strong><span>rekod disahkan</span></div><div><strong>${num(m.mean)} <small>/4</small></strong><span>purata rubrik disahkan (dalaman)</span></div></div><div class="notice">Laporan menggunakan penapis di atas. Purata rubrik mengira setiap tindakan dengan pemberat sama dan tidak menggantikan formula rasmi. GPS, PNGK, bilangan dan peratus kekal berasingan.</div><div class="report-options">${[['summary','Rumusan Pengurusan','Jumlah rekod dan status bagi setiap bidang.','chart'],['list','Daftar Penilaian','Jadual item, konteks, nilai dan status semakan.','file'],['evidence','Daftar Evidens','Fail dan pautan mengikut item serta tindakan.','link'],['detail','Laporan Terperinci','Skor tindakan, metrik, ulasan dan semakan.','book'],['incomplete','Rekod Belum Lengkap','Draf, pembetulan, nilai separa dan rekod tanpa evidens.','clock']].map(([type,h,p,ico])=>`<button class="report-option" data-action="report" data-type="${type}">${icon(ico)}<h3>${h}</h3><p>${p}</p></button>`).join('')}</div><section class="panel" style="margin-top:23px"><div class="section-title"><h3>Purata Rubrik Mengikut Bidang</h3><small>Rekod lengkap dan disahkan sahaja</small></div>${I.groups.filter(g=>!['A','5'].includes(g.id)).map(g=>{const v=E.summarize(rs.filter(r=>r.group===g.id&&r.status==='Disahkan'));return `<div class="chart-row"><div class="chart-label"><span>${esc(g.id+' · '+g.title)}</span><b>${num(v.mean)} /4</b></div><div class="chart-track"><i style="width:${v.percent||0}%;background:${g.color}"></i></div><small>${v.actions} tindakan · ${v.records} rekod</small></div>`;}).join('')}<p class="chart-note">Kiraan dalaman untuk rujukan pengurusan. Instrumen sumber tidak menyatakan wajaran skor keseluruhan.</p></section>`;}
function settingsPage(){if(S.user.role!=='admin')return empty('Akses terhad');const tab=S.settingsTab;return title('Tetapan Sistem','Urus akaun, identiti sekolah dan sambungan penyimpanan.')+`<div class="settings-tabs">${[['users','Pengguna'],['school','Sekolah'],['source','Instrumen Sumber'],['connection','Sambungan'],['logs','Log Aktiviti'],['legacy','Arkib V1']].map(([k,v])=>`<button type="button" class="btn small ${tab===k?'active':''}" data-action="settings-tab" data-id="${k}">${v}</button>`).join('')}</div><section class="panel">${settingsContent(tab)}</section>`;}
function settingsContent(tab){
 if(tab==='users')return `<div class="section-title"><h3>Pengguna & Hak Akses</h3>${btn('Tambah Pengguna','new-user','plus','primary small')}</div>${S.data.users.map(u=>`<div class="user-card"><div class="row"><span class="avatar">${esc(initials(u.name))}</span><div><p>${esc(u.name)} ${!u.active?'<span class="tag red">Tidak aktif</span>':''}</p><small>${esc(u.username)} · ${roles[u.role]}${u.role==='penyelaras'?' · '+esc(u.scopes.join(', ')):''}</small></div></div>${btn('Sunting','edit-user','edit','small',u.id)}</div>`).join('')}<div class="notice">Penyelaras membaca dan menyemak bidang yang ditugaskan. Guru / PPS membaca rekod sendiri dan rekod yang ditugaskan kepadanya.</div>`;
 if(tab==='school'){const v=S.data.settings;return `<h3 style="margin-bottom:20px">Identiti Sekolah</h3><form id="settings-form">${field('Nama sekolah','school',v.school||C.school,'text',true)}${field('Logo: pautan HTTPS atau ./assets/lencana.png','logo',v.logo||C.logo)}<div class="form-grid">${field('Tahun lalai','year',v.year||S.year,'number',true)}${field('Fasa lalai','cycle',v.cycle||S.cycle,'text',true)}</div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Simpan Tetapan</button></form>`;}
 if(tab==='source')return `<h3>Asas Instrumen Sistem</h3><p class="paragraph">${esc(I.source.title)} · ${esc(I.source.author)} · ${I.source.pages} halaman.</p><div class="notice">Metadata PDF bertarikh 10 Ogos 2023. Sistem merekod tahun penilaian yang dipilih; PDF ini tidak dilabel sebagai edisi rasmi 2026.</div><div class="mini-stat-grid"><div><b>70</b><small>item katalog</small></div><div><b>216</b><small>tindakan dengan rubrik</small></div><div><b>58</b><small>medan numerik</small></div></div><h3 style="margin:20px 0 10px">Pembetulan berbanding struktur awal</h3><ul class="info-list"><li>3.1.2.1–3.1.2.4 diasingkan kepada empat item yang berlainan.</li><li>3.1.2.3 ialah program peningkatan pencapaian murid; kod 3.1.7 tidak digunakan dalam instrumen ini.</li><li>3.2.3 ialah badan beruniform; Sukan untuk Semua ialah 3.2.6.</li><li>3.3.7 ialah Pentadbiran Psikometrik.</li></ul><a href="${I.source.pdf}" class="btn primary" target="_blank" rel="noopener">${icon('book')}Buka Dokumen Sumber</a>`;
 if(tab==='connection')return `<h3>Sambungan Google</h3><p class="paragraph" style="font-size:11px;word-break:break-all">${esc(C.apiUrl)}</p><div class="notice">Pasang ketiga-tiga fail Code.gs, Instrumen.gs dan Scoring.gs dalam projek yang sama. Jalankan setupSystem(), kemudian Deploy → Manage deployments → Edit → New version.</div>${btn('Uji Sambungan v2','health','refresh','primary')}<p class="paragraph">URL CSV asal dikekalkan dalam config.js sebagai rujukan. Ia tidak digunakan untuk rekod sulit atau kata laluan.</p>`;
 if(tab==='legacy')return `<h3>Arkib Sistem Versi 1</h3><p class="paragraph">Data versi lama pada helaian SKAS_ dikekalkan. Ia tidak ditukar secara automatik kerana beberapa kod awal berbeza daripada instrumen PDF.</p>${btn('Lihat Rekod Lama','legacy','file','primary')}<div id="legacy-results" style="margin-top:20px"></div>`;
 return S.data.logs.length?`<div class="table-wrap"><table><thead><tr><th>Tarikh</th><th>Pengguna</th><th>Tindakan</th></tr></thead><tbody>${S.data.logs.map(l=>`<tr><td>${date(l.createdAt)}</td><td>${esc(l.name)}</td><td>${esc(l.action)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada log aktiviti');
}
function openModal(h,html){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(h)}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Tutup">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!m.open)m.showModal();}
function closeModal(){if(S.user?.forcePassword)return;$('#modal').close();}
function modalActions(label='Simpan'){return `<div class="form-error" role="alert"></div><div class="modal-actions">${btn('Batal','close-modal')}<button type="submit" class="btn primary">${label}</button></div>`;}
function chooseItem(){openModal('Mulakan Penilaian',`<form id="choose-form">${selectField('Bidang','chooseGroup',I.groups.map(g=>option(g.id,g.id+' · '+g.title,S.group||'3.1')).join(''))}${selectField('Item instrumen','chooseItem',I.items.filter(i=>i.group===(S.group||'3.1')).map(i=>option(i.id,i.code+' · '+i.label,'')).join(''))}<div class="notice">Pilih item, kemudian isi konteks seperti panitia, unit, guru atau kelas. Setiap konteks boleh mempunyai penilaian sendiri.</div>${modalActions('Teruskan')}</form>`);}
function showEvidence(rid){const r=record(rid),i=item(r.itemId);openModal('Tambah Evidens',`<form id="evidence-form" data-id="${rid}">${field('Nama evidens','name','','text',true)}${selectField('Pautkan kepada tindakan / medan','actionId',option('','Keseluruhan item','')+(i.kind==='rubric'?i.actions.map(a=>option(a.id,a.id+') '+a.label,'')):i.fields.map(f=>option(f.id,f.title,''))).join(''))}${selectField('Jenis evidens','evidenceType',option('link','Pautan HTTPS','link')+option('file','Muat naik fail','link'))}<div id="evidence-input">${field('Pautan HTTPS','url','','url',true)}</div><div class="notice">Fail maksimum 5 MB. Sistem mengekalkan tetapan perkongsian Google Drive.</div>${modalActions('Tambah Evidens')}</form>`);}
function showReview(id,reopen=false){openModal(reopen?'Buka Semula Penilaian':'Semakan Penilaian',`<form id="review-form" data-id="${id}" data-reopen="${reopen}">${reopen?'':selectField('Keputusan','status',option('Disahkan','Disahkan','Disahkan')+option('Perlu Pembetulan','Perlu Pembetulan','Disahkan'))}${field('Maklum balas','feedback','','textarea',reopen)}${modalActions('Simpan Semakan')}</form>`);}
function showPassword(){openModal('Tukar Kata Laluan',`<form id="password-form">${S.user.forcePassword?'<div class="notice">Tukar kata laluan sementara sebelum meneruskan.</div>':''}${field('Kata laluan semasa','oldPassword','','password',true)}${field('Kata laluan baharu (minimum 12 aksara)','newPassword','','password',true)}${field('Sahkan kata laluan baharu','confirmPassword','','password',true)}<div class="form-error" role="alert"></div><div class="modal-actions">${S.user.forcePassword?'':btn('Batal','close-modal')}<button type="submit" class="btn primary">Tukar Kata Laluan</button></div></form>`);$('#f-oldPassword').minLength=1;$('#f-oldPassword').autocomplete='current-password';}
function showUser(id){const u=S.data.users.find(x=>x.id===id);openModal(u?'Sunting Pengguna':'Tambah Pengguna',`<form id="user-form" data-id="${id||''}"><div class="form-grid">${field('Nama penuh','name',u?.name||'','text',true)}${field('Nama pengguna','username',u?.username||'','text',true)}${selectField('Peranan','role',Object.entries(roles).map(([k,v])=>option(k,v,u?.role||'guru')).join(''))}${selectField('Status','active',option('true','Aktif',String(u?.active!==false))+option('false','Tidak aktif',String(u?.active!==false)))}${field(u?'Kata laluan sementara baharu (pilihan)':'Kata laluan sementara (minimum 12 aksara)','password','','password',!u,'span2')}<div class="span2"><label style="font-size:11px;font-weight:700">Skop Penyelaras</label>${I.groups.map(g=>`<label class="check-row"><input type="checkbox" name="scopes" value="${g.id}" ${u?.scopes.includes(g.id)?'checked':''}>${esc(g.id+' · '+g.title)}</label>`).join('')}</div></div>${modalActions()}</form>`);}
function showTask(){const groups=I.groups.filter(g=>scoped(g.id));openModal('Tetapkan Tugasan PPS',`<form id="task-form">${selectField('Bidang','taskGroup',groups.map(g=>option(g.id,g.id+' · '+g.title,'')).join(''))}${selectField('Item','itemId',I.items.filter(i=>i.group===groups[0]?.id).map(i=>option(i.id,i.id+' · '+i.label,'')).join(''))}<div class="form-grid">${field('Tahun','year',S.year,'number',true)}${field('Fasa','cycle',S.cycle,'text',true)}${field('Konteks / Unit','context','','text',true,'span2')}${selectField('Pegawai bertanggungjawab','assignedTo',S.data.users.filter(u=>u.active).map(u=>option(u.id,u.name,'')).join(''))}${field('Tarikh akhir','dueDate',today(),'date',true)}${field('Catatan tugasan','note','','textarea',false,'span2')}</div>${modalActions('Tetapkan Tugasan')}</form>`);}
function go(page,patch={},force=false){if(S.dirty&&!force){S.pending={page,patch};return openModal('Draf Belum Disimpan',`<p>Perubahan belum disimpan. Tinggalkan borang ini?</p><div class="modal-actions">${btn('Teruskan Mengisi','close-modal')}${btn('Tinggalkan Borang','discard','arrow','danger')}</div>`);}Object.assign(S,patch,{page,dirty:false});render();window.scrollTo({top:0,behavior:'auto'});}
function printHeader(h){return `<div class="print-header"><img class="print-logo" src="${logo()}" alt="Lencana sekolah"><div><p class="print-system-title">${esc(systemTitle())}</p><h1>${esc(school())}</h1><h2>${esc(h)}</h2><p class="print-small">SK@S 2.0 · ${esc(S.year)} · ${esc(S.cycle)} · Dijana ${date(new Date().toISOString())}${S.demo?' · MOD DEMONSTRASI':''}</p></div></div>`;}
function printable(r){const i=item(r.itemId);return `<section><h2>${esc(r.itemId+' · '+r.title)}</h2><p class="print-small">${esc(r.context)} · ${esc(r.status)} · ${esc(r.officer)} · ${date(r.date)}<br>Rujukan instrumen: halaman ${i.pages.join(', ')}.</p>${r.notApplicable?`<p><b>Tidak Berkaitan:</b> ${esc(r.naReason)}</p>`:r.kind==='rubric'?`<p><b>Purata dalaman:</b> ${num(r.computed.mean)} /4 · Jumlah ${num(r.computed.sum)} ÷ ${r.computed.scored} tindakan dinilai. ${r.computed.complete?'Lengkap':'Separa'}</p><table><thead><tr><th style="width:6%">Bil.</th><th style="width:26%">Tindakan</th><th style="width:7%">Skor</th><th>Rubrik Dipilih / Ulasan</th></tr></thead><tbody>${i.actions.map(a=>{const v=r.ratings[a.id];return `<tr><td>${a.id}</td><td>${esc(a.label)}</td><td>${num(v?.score)}</td><td>${v?.score!==null&&v?.score!==undefined?esc(a.rubric[v.score]):'Belum dinilai'}${v?.note?'<br><b>Ulasan:</b> '+esc(v.note):''}</td></tr>`;}).join('')}</tbody></table>`:`<table><thead><tr><th>Medan</th><th style="width:22%">Nilai / Unit</th><th>Asas / Catatan</th></tr></thead><tbody>${i.fields.map(f=>{const v=r.metrics[f.id]||{};return `<tr><td>${esc(f.title)}</td><td>${v.na?'Tidak Berkaitan':num(v.value)+' '+esc(f.unit)}</td><td>${v.na?esc(v.reason):f.type==='ratio'?num(v.numerator)+' ÷ '+num(v.denominator)+' × 100':f.referenceYearOffset?'Rumusan tahun '+(Number(r.year)-1):'—'}</td></tr>`;}).join('')}</tbody></table>`}<h3>Ulasan Pelaksanaan</h3><p>${esc(r.summary||'—')}</p><h3>Tindakan Penambahbaikan</h3><p>${esc(r.improvement||'—')}</p><h3>Evidens</h3>${r.evidence.length?`<ol>${r.evidence.map(e=>`<li>${esc(e.name)}${e.actionId?' · '+esc(e.actionId):''}<br><a href="${safeURL(e.url)}">${esc(e.url)}</a></li>`).join('')}</ol>`:'<p>Belum ada evidens.</p>'}<h3>Sejarah Semakan</h3>${S.data.reviews.filter(v=>v.recordId===r.id).map(v=>`<p>${esc(v.status)} · ${esc(v.reviewerName)} · ${date(v.createdAt)}<br>${esc(v.feedback||'—')}</p>`).join('')||'<p>Belum disemak.</p>'}<p class="print-small">Purata ialah kiraan dalaman tanpa wajaran rasmi keseluruhan. Metrik berlainan unit tidak digabungkan.</p></section>`;}
async function printReport(type,id){let rs=filtered(),h='',html='',landscape=false;
 if(type==='record'){h='Laporan Penilaian';html=printable(record(id));}
 else if(type==='detail'){h='Laporan Penilaian Terperinci';html=rs.map((r,i)=>`<div${i?' style="break-before:page"':''}>${printable(r)}</div>`).join('')||'<p>Tiada rekod.</p>';}
 else if(type==='summary'){h='Rumusan Pengurusan Sekolah';html=`<p>Ringkasan berdasarkan tahun, fasa, penapis dan rekod yang boleh diakses.</p><table><thead><tr><th>Bidang</th><th>Rekod</th><th>Disahkan</th><th>TB</th><th>Purata Rubrik Dalaman /4</th></tr></thead><tbody>${I.groups.map(g=>{const rows=rs.filter(r=>r.group===g.id),m=E.summarize(rows.filter(r=>r.status==='Disahkan'));return `<tr><td>${esc(g.id+' · '+g.title)}</td><td>${rows.length}</td><td>${rows.filter(r=>r.status==='Disahkan').length}</td><td>${rows.filter(r=>r.notApplicable).length}</td><td>${['A','5'].includes(g.id)?'Metrik berasingan':num(m.mean)}</td></tr>`;}).join('')}</tbody></table><h3>Kaedah Ringkasan</h3><p>Purata = jumlah skor tindakan dalam rekod rubrik lengkap dan disahkan ÷ bilangan tindakan yang dinilai. Setiap tindakan mempunyai pemberat sama bagi kiraan dalaman. Rekod Tidak Berkaitan tidak dimasukkan. Tiada wajaran rasmi keseluruhan diberikan dalam PDF sumber.</p>`;}
 else if(type==='evidence'){h='Daftar Evidens';landscape=true;const ev=rs.flatMap(r=>r.evidence.map(e=>({...e,itemId:r.itemId,context:r.context})));html=`<table><thead><tr><th style="width:5%">Bil.</th><th style="width:18%">Item / Konteks</th><th>Tindakan / Nama Evidens</th><th style="width:40%">Pautan</th></tr></thead><tbody>${ev.map((e,i)=>`<tr><td>${i+1}</td><td>${esc(e.itemId)}<br>${esc(e.context)}</td><td>${esc(e.actionId||'Keseluruhan')}<br>${esc(e.name)}</td><td>${esc(e.url)}</td></tr>`).join('')}</tbody></table>${ev.length?'':'<p>Tiada evidens.</p>'}`;}
 else{h=type==='incomplete'?'Penilaian Belum Lengkap':'Daftar Penilaian';landscape=true;if(type==='incomplete')rs=rs.filter(r=>r.status!=='Disahkan'||!r.computed.complete||!r.evidence.length&&!r.notApplicable);html=`<table><thead><tr><th style="width:5%">Bil.</th><th>Item / Tajuk</th><th>Konteks / Pegawai</th><th>Nilai</th><th>Evidens</th><th>Status</th></tr></thead><tbody>${rs.map((r,n)=>`<tr><td>${n+1}</td><td>${esc(r.itemId)}<br>${esc(r.title)}</td><td>${esc(r.context)}<br>${esc(r.officer)}</td><td>${r.notApplicable?'TB':r.kind==='rubric'?num(r.computed.mean)+' /4':r.computed.scored+'/'+r.computed.total+' medan'}</td><td>${r.evidence.length}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table>${rs.length?'':'<p>Tiada rekod.</p>'}`;}
 $('#print-area').innerHTML=printHeader(h)+html;let css=$('#print-orientation');if(!css){css=document.createElement('style');css.id='print-orientation';document.head.append(css);}css.textContent=`@media print{@page{size:A4 ${landscape?'landscape':'portrait'};margin:13mm}}`;
 if(document.fonts?.ready)await document.fonts.ready;const images=[...$('#print-area').querySelectorAll('img')];await Promise.all(images.map(im=>im.complete?Promise.resolve():Promise.race([new Promise(resolve=>{im.onload=resolve;im.onerror=resolve;}),new Promise(resolve=>setTimeout(resolve,2000))])));window.print();
}
function csvExport(){const rs=filtered();if(!rs.length)return toast('Tiada rekod untuk dieksport.');const rows=[['Tahun','Fasa','Kod','Tajuk','Bidang','Konteks','Tarikh','Pegawai','Status','Tidak Berkaitan','Sebab TB','Purata Rubrik Dalaman','Tindakan Dinilai','Jumlah Evidens','Data Metrik JSON'],...rs.map(r=>[r.year,r.cycle,r.itemId,r.title,group(r.group).title,r.context,r.date,r.officer,r.status,r.notApplicable?'Ya':'Tidak',r.naReason,r.kind==='rubric'&&r.computed.mean!==null?r.computed.mean:'',r.computed.scored,r.evidence.length,r.kind==='metric'?JSON.stringify(r.metrics):''])];const cell=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"',blob=new Blob(['\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SKAS_Penilaian_'+S.year+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
