 if(el.name==='taskGroup')$('#f-itemId').innerHTML=I.items.filter(i=>i.group===el.value).map(i=>option(i.id,i.code+' · '+i.label,'')).join('');
 if(el.name==='evidenceType')$('#evidence-input').innerHTML=el.value==='link'?field('Pautan HTTPS','url','','url',true):'<div class="form-field"><label for="file">Fail (maksimum 5 MB)</label><input id="file" name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.xls,.xlsx,.ppt,.pptx" required></div>';
 if(el.closest('#assessment-form')){S.dirty=true;if(el.name==='notApplicable'){$('#assessment-fields').disabled=el.checked;$('#whole-na-reason').hidden=!el.checked;}if(el.name.startsWith('metric:')&&el.name.endsWith(':na')){const card=el.closest('.metric-card');$('.metric-inputs',card).disabled=el.checked;$('.metric-na-reason',card).hidden=!el.checked;}updatePreview();}
