document.addEventListener('input',event=>{const el=event.target;if(el.id==='catalog-search'){S.catalog.search=el.value;$('#catalog-results').innerHTML=catalogCards();}if(['search','context'].includes(el.dataset.filter)){S.filters[el.dataset.filter]=el.value;if($('#record-results'))$('#record-results').innerHTML=recordTable(filtered());else if(S.page==='reports'){const id=el.id,pos=el.selectionStart;renderPage();const replacement=$('#'+id);replacement.focus();if(pos!==null)replacement.setSelectionRange(pos,pos);}}if(el.closest('#assessment-form')){S.dirty=true;updatePreview();}});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.id)return;event.preventDefault();if(working)return;const d=Object.fromEntries(new FormData(form)),intent=event.submitter?.value;
 if(form.id==='choose-form'){closeModal();return go('edit',{item:d.chooseItem,group:item(d.chooseItem).group,editingId:'',assignmentId:''});}
 working=true;const buttons=[...form.querySelectorAll('button')];buttons.forEach(x=>x.disabled=true);const error=$('.form-error',form)||$('#login-error');if(error)error.textContent='';
 try{
  if(form.id==='login-form'){S.demo=false;const out=await api('login',d);S.token=out.token;S.user=out.user;remember();if(S.user.forcePassword)return showPassword();S.page='dashboard';S.data=await api('bootstrap');S.user=S.data.user;S.year=String(S.data.settings.year||S.year);S.cycle=S.data.settings.cycle||S.cycle;render();return;}
  if(form.id==='password-form'){if(d.newPassword!==d.confirmPassword)throw new Error('Pengesahan kata laluan tidak sepadan.');S.user=await api('changePassword',{oldPassword:d.oldPassword,newPassword:d.newPassword});remember();$('#modal').close();await load();toast('Kata laluan ditukar.');return;}
  if(form.id==='assessment-form'){const r=formRecord(form);r.submit=intent==='submit';E.evaluate(item(r.itemId),r,r.submit,r.year);const saved=await api('saveRecord',{record:r});S.dirty=false;S.record=saved.id;S.page='detail';S.year=String(saved.year);S.cycle=saved.cycle;await load();toast(r.submit?'Penilaian dihantar.':'Draf disimpan. Tambah evidens pada halaman ini.');return;}
  if(form.id==='evidence-form'){const p={recordId:form.dataset.id,name:d.name,actionId:d.actionId};if(d.evidenceType==='link')p.url=d.url;else{const f=form.elements.file.files[0];if(!f||f.size>5242880)throw new Error('Pilih fail maksimum 5 MB.');p.base64=await fileBase64(f);p.mimeType=f.type||mimeFor(f.name);}await api('addEvidence',p);closeModal();await load();toast('Evidens ditambah.');return;}
  if(form.id==='remove-evidence-form'){await api('removeEvidence',{id:form.dataset.id,recordId:form.dataset.record});closeModal();await load();toast('Rujukan evidens dibuang.');return;}
  if(form.id==='review-form'){await api(form.dataset.reopen==='true'?'reopen':'review',{id:form.dataset.id,status:d.status,feedback:d.feedback});closeModal();await load();toast('Semakan disimpan.');return;}
  if(form.id==='delete-form'){await api('deleteRecord',{id:form.dataset.id});closeModal();S.page='records';await load();toast('Rekod dipadam.');return;}
  if(form.id==='task-form'){await api('saveAssignment',{assignment:d});closeModal();await load();toast('Tugasan ditetapkan.');return;}
  if(form.id==='delete-task-form'){await api('deleteAssignment',{id:form.dataset.id});closeModal();await load();toast('Tugasan dipadam.');return;}
  if(form.id==='user-form'){await api('saveUser',{user:{...d,id:form.dataset.id,active:d.active==='true',scopes:[...form.querySelectorAll('[name="scopes"]:checked')].map(x=>x.value)}});closeModal();await load();toast('Pengguna disimpan.');return;}
  if(form.id==='settings-form'){await api('saveSettings',{settings:d});await load();toast('Tetapan sekolah disimpan.');return;}
 }catch(e){if(error?.isConnected)error.textContent=e.message;else toast(e.message,true);}finally{working=false;buttons.forEach(x=>x.disabled=false);}
});
function fileBase64(f){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('Fail tidak dapat dibaca.'));r.readAsDataURL(f);});}
function mimeFor(n){return ({pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation'})[n.split('.').pop().toLowerCase()]||'application/octet-stream';}
function demoData(){
 const year=String(new Date().getFullYear()),cycle='Penilaian Kendiri',stamp=new Date().toISOString(),user={id:'demo-admin',username:'demo',name:'Pentadbir Demo',role:'admin',scopes:I.groups.map(g=>g.id),active:true,forcePassword:false};
 const data={user,users:[user,{id:'demo-guru',username:'guru.demo',name:'Guru Contoh',role:'guru',scopes:[],active:true},{id:'demo-coord',username:'penyelaras.demo',name:'Penyelaras Contoh',role:'penyelaras',scopes:['3.1'],active:true}],records:[],reviews:[],assignments:[],logs:[],settings:{school:C.school,logo:C.logo,year,cycle},instrumentVersion:I.version};
 const examples=[['1.1.1','Pengurusan Sekolah','Disahkan'],['3.1.2.1','Panitia Sains','Dihantar'],['3.2.3.1','Pengakap','Draf'],['3.3.7.1','Unit Bimbingan & Kaunseling','Perlu Pembetulan'],['4.1.1','Guru Contoh · Sains Tahun 3','Disahkan'],['A1','Profil Guru','Disahkan'],['A8','Sekolah tanpa asrama','Disahkan'],['5.1.1','Sains · Tahun 3','Disahkan'],['5.2.1','Kelab/Persatuan','Draf']];
 examples.forEach(([id,context,status],n)=>{const i=item(id),ratings={},metrics={};if(i.kind==='rubric')i.actions.forEach((a,j)=>ratings[a.id]={score:n===2&&j>1?null:Math.min(4,3+j%2),note:'Catatan demonstrasi berdasarkan semakan dokumen.'});else i.fields.forEach((f,j)=>{if(f.type==='ratio')metrics[f.id]={numerator:j===0?45:j===1?42:j===2?7:3,denominator:j<3?45:8,na:false};else metrics[f.id]={value:i.id==='5.1.1'?[0,5,15,30,30,20,0,10,20,30,25,15][j]:2.15,na:false};});const seed={ratings,metrics,notApplicable:id==='A8',naReason:id==='A8'?'Contoh: sekolah tidak mempunyai asrama.':''},calc=E.evaluate(i,seed,false,year);const r={id:'DEMO-'+n,itemId:id,group:i.group,kind:i.kind,title:i.label,context,year,cycle,date:today(),officer:'Guru Contoh',ownerId:user.id,assignedTo:user.id,assignmentId:'',notApplicable:seed.notApplicable,naReason:seed.naReason,...calc,summary:'Data contoh untuk demonstrasi. Dapatan penilaian direkod mengikut panduan instrumen.',improvement:'Memperkemas dokumentasi dan tindakan susulan.',evidence:n===0?[{id:'DEMO-EV',name:'Contoh pautan evidens',url:'https://drive.google.com/',mimeType:'link',size:0,actionId:'a'}]:[],status,feedback:'',createdAt:stamp,updatedAt:stamp,revision:1};data.records.push(r);if(status==='Disahkan')data.reviews.push({id:'REV-'+n,recordId:r.id,status,feedback:'Semakan contoh untuk demonstrasi.',reviewerName:'Penyelaras Contoh',createdAt:stamp});});
 data.assignments=[{id:'DEMO-TASK',year,cycle,itemId:'3.1.2.3',group:'3.1',context:'Program Intervensi Sains',assignedTo:user.id,dueDate:today(),note:'Contoh tugasan PPS. Lengkapkan penilaian dan evidens.'}];return data;
}
function demoAPI(a,p={}){
 const data=S.data,id=()=>clientId(),now=()=>new Date().toISOString();if(a==='health')return {app:'SKAS',version:I.version,ready:true,sourceHash:I.source.sha256};if(a==='bootstrap')return data;
 if(a==='changePassword'){S.user.forcePassword=false;return S.user;}if(a==='legacy')return [];
 if(a==='saveRecord'){const d=p.record,i=item(d.itemId),old=record(d.id);if(!d.context||!d.cycle)throw new Error('Konteks dan fasa diperlukan.');if(d.submit&&!d.notApplicable&&!d.summary)throw new Error('Ulasan pelaksanaan diperlukan.');const calc=E.evaluate(i,d,!!d.submit,d.year),r={...old,...d,...calc,id:old?.id||id(),group:i.group,kind:i.kind,title:i.label,ownerId:old?.ownerId||S.user.id,officer:d.officer||S.user.name,evidence:old?.evidence||[],status:d.submit?'Dihantar':'Draf',revision:Number(old?.revision||0)+1,createdAt:old?.createdAt||now(),updatedAt:now()};if(old)Object.assign(old,r);else data.records.push(r);return r;}
 if(a==='review'||a==='reopen'){const r=record(p.id);r.status=a==='reopen'?'Perlu Pembetulan':p.status;if(r.status==='Perlu Pembetulan'&&!p.feedback)throw new Error('Masukkan maklum balas pembetulan.');r.feedback=p.feedback;r.revision++;r.updatedAt=now();data.reviews.push({id:id(),recordId:r.id,status:r.status,feedback:p.feedback,reviewerName:S.user.name,createdAt:now()});return r;}
 if(a==='deleteRecord'){data.records=data.records.filter(r=>r.id!==p.id);data.reviews=data.reviews.filter(r=>r.recordId!==p.id);return true;}
 if(a==='addEvidence'){if(p.base64)throw new Error('Muat naik fail tersedia melalui sambungan sebenar. Gunakan pautan HTTPS dalam demo.');if(!/^https:\/\//.test(p.url||''))throw new Error('Gunakan pautan HTTPS.');const r=record(p.recordId);r.evidence.push({id:id(),name:p.name,actionId:p.actionId,url:p.url,mimeType:'link',size:0,createdAt:now()});r.revision++;return r;}
 if(a==='removeEvidence'){const r=record(p.recordId);r.evidence=r.evidence.filter(e=>e.id!==p.id);r.revision++;return r;}
 if(a==='saveAssignment'){const t={...p.assignment,id:id(),group:item(p.assignment.itemId).group};data.assignments.push(t);return t;}
 if(a==='deleteAssignment'){data.assignments=data.assignments.filter(t=>t.id!==p.id);return true;}
 if(a==='saveUser'){const u={...p.user,id:p.user.id||id()};delete u.password;const old=data.users.find(x=>x.id===u.id);if(old)Object.assign(old,u);else data.users.push(u);return u;}
 if(a==='saveSettings'){data.settings=p.settings;return p.settings;}if(a==='logout')return true;throw new Error('Tindakan demo tidak tersedia.');
}
async function init(){
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
 window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});
 window.addEventListener('online',()=>{if(S.data&&!S.dirty)render();toast('Sambungan Internet dipulihkan.');});
 window.addEventListener('offline',()=>{if(S.data&&!S.dirty)render();toast('Luar talian. Data belum disimpan memerlukan Internet.',true);});
 $('#modal').addEventListener('cancel',e=>{if(S.user?.forcePassword)e.preventDefault();});
 try{const saved=JSON.parse(sessionStorage.getItem('skas-v2-session')||'null');if(saved?.token&&saved.user){S.token=saved.token;S.user=saved.user;}}catch{}
 loginView();
 if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>toast('PWA belum tersedia. Semak fail hosting.',true));
 if(S.user&&S.token){if(S.user.forcePassword)showPassword();else try{await load();}catch(e){toast(e.message,true);}}
}
init();
